// Generated by scripts/gen-packs.mjs from src/words.ts (a copy, so the console runs the server's words engine). Do not edit: run `npm run gen:packs`.
/**
 * The words engine (mold_v0-100): pure, no imports, so the server (src/vocabulary.ts), the console (gen-packs copies
 * this file to web/src/lib/words.generated.ts) and gen-packs itself (node strips the types) all run the same code.
 *
 * The shell writes no concept word of any product. Its text writes a placeholder, and the build's words fill it:
 *
 *   {run} {runs} {Run} {Runs}                     what one unit of agent work is called ("run"; "audit"; "simulation")
 *   {workspace} {workspaces} {Workspace} ...      the tenant ("workspace"; "company")
 *   {account} {accounts} ...                      the paying account ("account")
 *   {member} {members} ...                        a person of a workspace ("member"; "analyst")
 *   {owner} {owners} ...                          the person who owns the account ("owner")
 *   {tool_call} {tool_calls} {key} {keys} ...     an MCP tool call, an API key
 *   {product} {Product}                           the app's name (profile.json `name`)
 *
 * A lower-case key gives the word as written mid-sentence, a capitalised one (first letter raised) the word for the
 * start of a sentence or a label. "a {run}" and "A {run}" take the article of the word they get ("an audit").
 *
 * The words, last wins: BASE (the neutral default profile's, below and in scripts/gen-packs.mjs DEFAULT_PROFILE),
 * then the packs' pack.json `words` (the first pack that names a word), then the app's own profile.json `words` (a
 * host pack's `host.profile.words` under it). A layer that names a word may name its plural too (`runs`), else the
 * plural is made by the rule below.
 */

/** The shell's words: one key per thing it names, singular; the plural is the key with `s`. */
export const WORD_KEYS = ["workspace", "account", "member", "owner", "run", "tool_call", "key"] as const;
export type WordKey = (typeof WORD_KEYS)[number];
export type Words = Record<WordKey | `${WordKey}s`, string>;

/** The neutral words, held in the default profile: what a build with no pack and no profile `words` says. */
export const BASE_WORDS: Readonly<Words> = Object.freeze({
  workspace: "workspace", workspaces: "workspaces",
  account: "account", accounts: "accounts",
  member: "member", members: "members",
  owner: "owner", owners: "owners",
  run: "run", runs: "runs",
  tool_call: "tool call", tool_calls: "tool calls",
  key: "key", keys: "keys",
});

/** "audit" -> "audits", "batch" -> "batches", "policy" -> "policies" (the rule src/mcp-catalog.ts names tools by). */
export const pluralWord = (w: string): string => (/(s|x|z|ch|sh)$/.test(w) ? `${w}es` : /[^aeiou]y$/.test(w) ? `${w.slice(0, -1)}ies` : `${w}s`);
/** The first letter raised. */
export const capWord = (w: string): string => (w ? w[0]!.toUpperCase() + w.slice(1) : w);
/** "a" or "an" before a word ("an audit", "a simulation", "a user"). */
export const articleFor = (w: string): "a" | "an" => (/^[aeiou]/i.test(w) && !/^(uni|use|usu|eu|one)/i.test(w) ? "an" : "a");

/** A word as a profile or pack may give it: plain text, 1 to 40 characters, no markup, no braces, no line break. */
export const wordProblem = (v: unknown): string | null =>
  typeof v !== "string" || !v.trim() || v.length > 40 || /[<>{}"`\\\r\n]/.test(v) ? "a word of 1 to 40 characters, no markup, braces, quotes or line breaks" : null;

/**
 * The build's words: `layers` from the highest (the profile's) to the lowest (the last pack's), over BASE_WORDS. The
 * first layer that names a word gives it; its plural comes from the first layer that names the word or its plural.
 */
export function resolveWords(layers: readonly (Readonly<Record<string, string>> | null | undefined)[]): Words {
  const out = { ...BASE_WORDS } as Record<string, string>;
  const has = (l: Readonly<Record<string, string>> | null | undefined, k: string) => typeof l?.[k] === "string" && l[k]!.trim() !== "";
  for (const k of WORD_KEYS) {
    const one = layers.find((l) => has(l, k));
    if (one) out[k] = one[k]!.trim();
    // The plural: from the highest layer that names the word or its plural (its own plural, else made from its word).
    const many = layers.find((l) => has(l, k) || has(l, `${k}s`));
    if (many) out[`${k}s`] = has(many, `${k}s`) ? many[`${k}s`]!.trim() : pluralWord(many[k]!.trim());
  }
  return out as Words;
}

const KEYS = new Set<string>([...WORD_KEYS, ...WORD_KEYS.map((k) => `${k}s`), "product"]);
// An optional article before the placeholder, so it can be made to agree: "a {run}" -> "an audit".
const PLACEHOLDER = /(\b[Aa]n? )?(?<!\$)\{([A-Za-z_]+)\}/g;

/** The word for one placeholder key (`run`, `Runs`, `product`), or null when it is not one. */
export function wordOf(words: Readonly<Words>, product: string, key: string): string | null {
  const lower = key[0]!.toLowerCase() + key.slice(1);
  if (!KEYS.has(lower)) return null;
  const w = lower === "product" ? product : (words as Record<string, string>)[lower]!;
  return key === lower ? w : capWord(w);
}

/** Text with its placeholders filled from `words` and `product` (and their articles agreeing); anything else as it is. */
export function fillWith(words: Readonly<Words>, product: string, text: string): string {
  if (!text.includes("{")) return text;
  return text.replace(PLACEHOLDER, (m, article: string | undefined, key: string) => {
    const w = wordOf(words, product, key);
    if (w == null) return m;
    if (!article) return w;
    const a = articleFor(w);
    return `${article[0] === "A" ? capWord(a) : a} ${w}`;
  });
}

/** The placeholders a text uses that are not one of the shell's (a typo: `{rnu}`), for checks. */
export const unknownPlaceholders = (text: string): string[] =>
  [...text.matchAll(PLACEHOLDER)].map((m) => m[2]!).filter((k) => !KEYS.has(k[0]!.toLowerCase() + k.slice(1)));
